<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$kid=(int)$_POST['id_klaim'];$receiver=trim($_POST['penerima']??'');$note=trim($_POST['catatan']??'');if($receiver){$s=$koneksi->prepare("SELECT id_laporan,id_user FROM klaim WHERE id_klaim=? AND status_klaim='disetujui'");$s->bind_param('i',$kid);$s->execute();$r=$s->get_result()->fetch_assoc();if($r){$admin=(int)currentUser()['id_user'];$s=$koneksi->prepare('INSERT INTO pengambilan(id_klaim,id_admin,nama_penerima,catatan) VALUES(?,?,?,?)');$s->bind_param('iiss',$kid,$admin,$receiver,$note);$s->execute();$s=$koneksi->prepare("UPDATE klaim SET status_klaim='diambil' WHERE id_klaim=?");$s->bind_param('i',$kid);$s->execute();$s=$koneksi->prepare("UPDATE laporan SET status='selesai' WHERE id_laporan=?");$s->bind_param('i',$r['id_laporan']);$s->execute();notifyUser($koneksi,(int)$r['id_user'],'Barang telah diambil','Pengambilan barang berhasil dicatat.','siswa/klaim.php');flash('Pengambilan barang berhasil dicatat.');}}redirect('admin/pengambilan.php');}$pageTitle='Pengambilan Barang';$rows=$koneksi->query("SELECT k.id_klaim,k.created_at,l.nama_barang,u.nama FROM klaim k JOIN laporan l ON l.id_laporan=k.id_laporan JOIN users u ON u.id_user=k.id_user WHERE k.status_klaim='disetujui' ORDER BY k.created_at");$history=$koneksi->query('SELECT p.*,l.nama_barang FROM pengambilan p JOIN klaim k ON k.id_klaim=p.id_klaim JOIN laporan l ON l.id_laporan=k.id_laporan ORDER BY p.tanggal_pengambilan DESC LIMIT 30');require __DIR__.'/../includes/header.php';?><div class="section-grid"><div class="panel"><h2>Catat pengambilan</h2><?php if(!$rows->num_rows):?><div class="empty">Tidak ada klaim yang menunggu pengambilan.</div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><div class="field"><label>Klaim disetujui</label><select name="id_klaim"><?php while($r=$rows->fetch_assoc()):?><option value="<?=$r['id_klaim']?>">#<?=$r['id_klaim']?> · <?=e($r['nama_barang'])?> · <?=e($r['nama'])?></option><?php endwhile;?></select></div><div class="field"><label>Nama penerima</label><input name="penerima" required></div><div class="field"><label>Catatan</label><textarea name="catatan"></textarea></div><button class="btn">Konfirmasi pengambilan</button></form><?php endif;?></div><div class="panel"><h2>Riwayat pengambilan</h2><?php while($r=$history->fetch_assoc()):?><div class="item"><div class="item-thumb"></div><div class="item-info"><b><?=e($r['nama_barang'])?></b><small><?=e($r['nama_penerima'])?> · <?=e(date('d/m/Y H:i',strtotime($r['tanggal_pengambilan'])))?></small></div></div><?php endwhile;?></div></div><?php require __DIR__.'/../includes/footer.php';?>
